   "template": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>AwwO Studio · Showreel</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=Inter:wght@400;600;800&family=Bebas+Neue&family=Playfair+Display:wght@500;700&family=JetBrains+Mono:wght@400;700&family=Instrument+Serif&display=block\">\n<style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#05070c}#film,#overlay{position:fixed;inset:0;width:100%;height:100%;display:block}#overlay{pointer-events:none}#play{position:fixed;left:14px;bottom:14px;z-index:2;font:600 13px/1 system-ui,sans-serif;padding:8px 12px;border-radius:6px;border:1px solid rgba(255,255,255,.35);background:rgba(0,0,0,.45);color:#fff;cursor:pointer}html[data-rendering] #play{display:none}</style>\n</head>\n<body>\n<canvas id=\"film\"></canvas>\n<button id=\"play\" type=\"button\">Play</button>\n<script>window.FILM_SHEET = {{in:from_director_sheet}};</script>\n<script>{{in:from_kernel}}</script>\n<script>{{in:from_brands-a}}</script>\n<script>{{in:from_brands-b}}</script>\n<script>{{in:from_studio}}</script>\n<script>{{in:from_sound}}</script>\n<script>F.boot();</script>\n</body>\n</html>\n",
